/* SPDX-License-Identifier: GPL-2.0 */
/*
 * Emit lib/libtest_lz4_generated.h.
 *
 * The plaintext is generated by lt_l4gen() below and compressed by the SYSTEM
 * liblz4, not by lib/lz4/lz4_compress.c -- see port/test/lz4/sysenc.c for why.
 * The expectation therefore comes from outside this project: liblz4 produced
 * the stream and the kernel has to reproduce the plaintext.
 *
 * THE RULES IN lt_l4gen() ARE THE SAME RULES lib/libtest.c USES. If the two
 * drift, the vectors decode correctly and are compared against a plaintext
 * nothing produced. gen-vectors.sh diffs the two copies on every run.
 */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef uint8_t u8;
typedef uint32_t u32;

extern int LZ4_compress_default(const char *src, char *dst, int n, int cap);

/* LT_L4GEN_BEGIN */
static void lt_l4gen(int kind, u8 *b, unsigned int n)
{
	u32 s = 0x2468ace0u + (u32)kind * 2654435761u;
	unsigned int i;

	for (i = 0; i < n; i++) {
		s = s * 1103515245u + 12345u;
		switch (kind) {
		case 0:				/* incompressible */
			b[i] = (u8)(s >> 24);
			break;
		case 1:				/* long runs */
			b[i] = (u8)((i / 97) & 0xff);
			break;
		case 2:				/* short alphabet */
			b[i] = (u8)('a' + ((s >> 20) & 3));
			break;
		case 3:				/* back-references */
			if (i >= 64 && ((s >> 16) & 1))
				b[i] = b[i - 64];
			else
				b[i] = (u8)('A' + ((s >> 22) & 15));
			break;
		default:
			/* SMALL PERIODS 1..8, which is the only thing that
			 * reaches the offset < 8 match path and its
			 * inc32table/dec64table steps. Without this shape a
			 * sabotage of dec64table[4] passed every kernel
			 * vector. */
			b[i] = (u8)(0x30 + (i % (1 + (i / 512) % 8)));
			break;
		}
	}
}
/* LT_L4GEN_END */

int main(void)
{
	static const unsigned int lens[4] = { 61, 1021, 4093, 16381 };
	static u8 plain[16384];
	static char comp[32768];
	int kind;
	unsigned int v = 0;

	printf("/* SPDX-License-Identifier: GPL-2.0 */\n");
	printf("/*\n");
	printf(" * GENERATED by port/test/lz4/gen-vectors.sh -- do not edit.\n");
	printf(" *\n");
	printf(" * Five plaintext shapes at four lengths, compressed by the SYSTEM\n");
	printf(" * liblz4 rather than by lib/lz4/lz4_compress.c -- see\n");
	printf(" * port/test/lz4/sysenc.c. The plaintext is NOT stored: it is\n");
	printf(" * regenerated by lt_l4gen() in lib/libtest.c, whose rules\n");
	printf(" * gen-vectors.sh checks against the generator on every run.\n");
	printf(" */\n\n");

	for (kind = 0; kind < 5; kind++) {
		unsigned int li;

		for (li = 0; li < 4; li++) {
			unsigned int n = lens[li];
			int cl;
			int j;

			lt_l4gen(kind, plain, n);
			cl = LZ4_compress_default((const char *)plain, comp,
						  (int)n, (int)sizeof(comp));
			if (cl <= 0)
				return 2;

			printf("static const u8 lt_l4c_%u[] __initconst = {\n", v);
			for (j = 0; j < cl; j += 12) {
				int k;

				printf("\t");
				for (k = j; k < cl && k < j + 12; k++)
					printf("0x%02x,", (unsigned char)comp[k]);
				printf("\n");
			}
			printf("};\n\n");
			v++;
		}
	}

	printf("struct lt_l4vec {\n");
	printf("\tconst u8 *comp;\n");
	printf("\tunsigned int comp_len;\n");
	printf("\tunsigned int plain_len;\n");
	printf("\tint kind;\n");
	printf("};\n\n");
	printf("static const struct lt_l4vec lt_l4vecs[] __initconst = {\n");

	v = 0;
	for (kind = 0; kind < 5; kind++) {
		unsigned int li;

		for (li = 0; li < 4; li++) {
			unsigned int n = lens[li];
			int cl;

			lt_l4gen(kind, plain, n);
			cl = LZ4_compress_default((const char *)plain, comp,
						  (int)n, (int)sizeof(comp));
			printf("\t{ lt_l4c_%u, %d, %u, %d },\n", v, cl, n, kind);
			v++;
		}
	}
	printf("};\n");
	return 0;
}
